# Print out some observations of the test input
G = None

# Load grids from this session
d = os.environ['RLM_SESSION_DIR']
session_name = os.path.basename(d)
log_path = os.path.normpath(os.path.join(os.environ['RLM_SESSION_DIR'], '..', '..', 'sessions', session_name + '.jsonl'))

with open(log_path) as f:
    t = f.read()

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    # Extract the grid rows after this match
    end_pos = m.end()
    remaining = t[end_pos:]
    # Look for the next grid marker to know where this one ends
    next_marker = None
    for m2 in re.finditer(r'(Demo pair |\d+x\d+):', remaining):
        if m2.group(1) or 'x' in m2.group(2):
            next_marker = m2.end()
            break
    if next_marker:
        rows_str = remaining[:next_marker].split('\n')[:h]
    else:
        rows_str = remaining.split('\n')[:h]

    if k not in G:
        try:
            rows = [[int(x) for x in row.split()] for row in rows_str if row.strip()]
            if all(len(row) == w for row in rows):
                G[k] = rows
        except:
            pass

if G:
    print("Grid shape:", len(G.get('Test input', [])), "x", len(G.get('Test input', [[]])[0]))

