# Parse JSONL session log
import json
import re

d = os.environ['RLM_SESSION_DIR']
session_name = os.path.basename(d)
log_path = os.path.normpath(os.path.join(os.environ['RLM_SESSION_DIR'], '..', '..', 'sessions', session_name + '.jsonl'))

G = {}

with open(log_path) as f:
    for line in f:
        obj =(json.loads(line.strip()) if line.strip() else None)
        if not obj:
            continue

        # Check for grid content
        if 'content' in obj:
            content = obj['content']
            # Look for grid markers in content
            matches = re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.+?)(?=\n{2,}|$|{"type"|Demo pair|\D{4,}Test input)', content, re.DOTALL)
            for m in matches:
                k, h, w = m.group(1), int(m.group(2)), int(m.group(3))
                grid_rows = []
                # Next is the grid row by row
                remaining = content[m.end():m.end()+h*w*300]  # rough chunk
                lines = remaining.split('\n')[:h]
                for line in lines:
                    parts = line.strip().split()
                    if parts:
                        try:
                            grid_rows.append([int(x) for x in parts])
                        except:
                            pass
                if k not in G and grid_rows:
                    G[k] = grid_rows

print("Found grids:", list(G.keys()))
for k, v in sorted(G.items()):
    print(f"  {k}: {len(v)}x{len(v[0]) if v else '?'}")

